/**
 * The tips as a screen uses them: the feature and this device's state, read
 * live, settled once the feature is on, and a tip held on screen once shown.
 */
import { useEffect, useState } from 'react';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { LEARN_OFF, loadLearn, markTipShown, settleTips, type LearnView } from './state.js';
import type { TipId } from './tips.js';

/**
 * The feature and this device's tips, live. `ready` is false until the first
 * read lands, so nothing is drawn on a guess and then taken back.
 */
export function useLearn(): LearnView & { ready: boolean } {
  // An async arrow: Dexie follows the reads past the first await only inside
  // an async querier, and the tips are read after the flag.
  const read = useLiveQuery<LearnView | null>(async () => loadLearn(), null, []);
  const view = read ?? LEARN_OFF;
  // Settled here, in an effect, never in the query above: the write would
  // retrigger the query that made it.
  useEffect(() => {
    if (view.on && view.tips === null) void settleTips();
  }, [view.on, view.tips]);
  return { ...view, ready: read !== null };
}

/**
 * Holds the tip a screen picked for one moment (`moment`: a card, a visit)
 * and marks it shown, once. Marking puts it away, so the next pick would no
 * longer return it; holding it keeps it on screen until the moment changes,
 * and a later moment picks afresh.
 */
export function useHeldTip(pick: TipId | undefined, moment: string): TipId | undefined {
  const [held, setHeld] = useState<{ moment: string; id: TipId } | undefined>(undefined);
  // Adjusting state while rendering, React's own pattern for a value derived
  // from props that must then stay put: no effect, no extra frame.
  // A new moment drops what the last one held, so coming back to that
  // moment later (the same notebook again) does not bring it back.
  if (held?.moment !== moment && (pick !== undefined || held !== undefined)) {
    setHeld(pick === undefined ? undefined : { moment, id: pick });
  }
  const shown = held?.moment === moment ? held.id : undefined;
  useEffect(() => {
    if (shown !== undefined) void markTipShown(shown);
  }, [shown, moment]);
  return shown;
}
