import { useEffect, useState } from 'react';
import { modes as modesApi } from '@/api/endpoints.js';
import { isApiError } from '@/api/errors.js';
import { SRS_OFF, loadSrsView, type SrsView } from '@/features/schedule/data.js';
import { useSay } from '@/features/settings/useSay.js';
import { t } from '@/i18n/index.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { useOnline } from '@/lib/useOnline.js';
import { applyFreezeAnswer } from '@/sync/streak.js';
import { refreshSrs } from '@/sync/srs.js';

/** The streak freeze switch, wherever it is offered. */
export interface FreezeSwitch {
  srs: SrsView;
  /** The flag's copy has been read: until then nothing is offered on a guess. */
  ready: boolean;
  online: boolean;
  saving: boolean;
  /** Another app of the account is too old: turning on waits for it. */
  older: boolean;
  /** The outcome of the last change, for a status line. */
  status: string | undefined;
  failed: boolean;
  /** Asks the server to turn freeze on or off; a refusal changes nothing here. */
  change: (next: boolean) => Promise<boolean>;
}

/**
 * One switch, two places (SRS v2): the row on Settings → Practice and the
 * streak sheet on Today. The switch is the server's (`PUT /me/streak-freeze`),
 * so it needs a connection, and it waits while another app of the account is
 * too old to keep the same streak. Which apps are too old is read fresh when
 * the switch could be shown (`active`).
 */
export function useFreezeSwitch(active = true): FreezeSwitch {
  const read = useLiveQuery<SrsView | null>(loadSrsView, null, []);
  const srs = read ?? SRS_OFF;
  const online = useOnline();
  const [saving, setSaving] = useState(false);
  const { status, failed, say } = useSay();
  const enabled = active && srs.enabled;
  useEffect(() => {
    if (enabled) void refreshSrs({ force: true }).catch(() => undefined);
  }, [enabled]);

  const change = async (next: boolean): Promise<boolean> => {
    setSaving(true);
    try {
      await applyFreezeAnswer(await modesApi.setStreakFreeze(next));
      say('');
      return true;
    } catch (error) {
      if (isApiError(error, 'conflict')) say(t('streakFreeze.olderDevices'), true);
      else if (isApiError(error, 'offline')) say(t('streakFreeze.offline'), true);
      else if (isApiError(error, 'forbidden')) say(t('schedule.unavailableBody'), true);
      else say(t('streakFreeze.error'), true);
      return false;
    } finally {
      setSaving(false);
    }
  };

  return {
    srs,
    ready: read !== null,
    online,
    saving,
    older: srs.olderDevices.length > 0,
    status,
    failed,
    change,
  };
}
